{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0002",
          "reason": "Current IAEA legal-status page is useful baseline context, but it is not a 2022 contemporaneous record of Sisi's conduct."
        },
        {
          "evidence_id": "E0005",
          "reason": "Civilian nuclear-energy sponsorship is not, by itself, evidence of existential-risk restraint or command-and-control stewardship."
        },
        {
          "evidence_id": "E0006",
          "reason": "Construction licensing shows regulatory process, not demonstrated nuclear-safety performance or ruler-attributed risk reduction."
        },
        {
          "evidence_id": "E0008",
          "reason": "Project-start chronology is civilian infrastructure context, not direct evidence of prudent existential-risk governance."
        },
        {
          "evidence_id": "E0013",
          "reason": "The CTBT non-ratification explanation is state foreign-policy posture, not direct 2022 ruler-level risk management."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct evidence of Sisi personally making a 2022 nuclear-safety, command-and-control, or crisis-escalation choice.",
          "lenses": ["1B.3", "1B.7", "1B.8", "1B.9"],
          "best_source_or_query_direction": "ENRRA/IAEA safety implementation records, treaty implementation documents, and any official emergency-preparedness or cyber/physical protection materials",
          "why_it_matters": "Without a direct ruler-attributed risk-bearing choice, the chapter risks treating civilian nuclear development as if it were existential-risk stewardship."
        }
      ],
      "reason": "The package fairly shows limited exposure, treaty diplomacy, and a civilian nuclear buildout, but it does not yet show a direct ruler-attributed existential-risk decision or measurable safety improvement in 2022."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Concrete durable-conflict outcomes are thin beyond mediation and de-escalatory posture.",
          "lenses": ["2B.7", "2B.10"],
          "best_source_or_query_direction": "UN ceasefire records, conflict-party statements, mediation documentation, and post-event implementation reporting",
          "why_it_matters": "It distinguishes rhetorical restraint from actual conflict reduction and durable peace effects."
        }
      ],
      "reason": "The package fairly presents limited-exposure diplomacy, mediation in Gaza, and de-escalatory regional posture, while preserving contrary evidence that outcomes were fragile and unresolved."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Exact chains of command and the effectiveness of pardon/reform mechanisms remain opaque.",
          "lenses": ["3B.4", "3B.5", "3B.10"],
          "best_source_or_query_direction": "Court records, independent inquiries, UN special procedures, and named command-accountability findings",
          "why_it_matters": "It helps separate tolerated state abuse from direct orders and tests whether remedial steps were substantive."
        }
      ],
      "reason": "The package fairly shows severe domestic repression, weak accountability, and limited remedial action, while preserving contrary evidence and not over-claiming personal order for every abuse."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0035",
          "reason": "Official national-dialogue framing is state self-presentation, not independent proof of meaningful political contestability."
        },
        {
          "evidence_id": "E0045",
          "reason": "The human-rights-strategy report is a government self-assessment and should not be treated as independent evidence of liberalization."
        }
      ],
      "material_gaps": [
        {
          "gap": "There was no 2022 election, so contestability and transfer-rule evidence remains mostly structural rather than event-based.",
          "lenses": ["4B.1", "4B.8", "4B.10"],
          "best_source_or_query_direction": "Election-administration records, party/court filings, observer reports, and institutional-autonomy documentation",
          "why_it_matters": "It helps distinguish a controlled dialogue from actual meaningful political competition and self-binding."
        }
      ],
      "reason": "The package fairly shows a tightly controlled authoritarian system with limited dialogue and selective concessions, while independent press-freedom and rights reporting preserves the contrary evidence."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0060",
          "reason": "This is a later retrospective baseline on the investment climate, so it should be used only as context, not as contemporaneous 2022 performance evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "Household-level distribution and implementation depth of the reform package are still thin.",
          "lenses": ["5B.8", "5B.9", "5B.10"],
          "best_source_or_query_direction": "Household surveys, budget-execution data, firm-level investment records, and program implementation audits",
          "why_it_matters": "It separates announcement and stabilization from actual welfare and competitiveness effects."
        }
      ],
      "reason": "The package fairly shows crisis management, devaluation, IMF-backed reform, and inflationary downside in the same year, so the economic story is balanced rather than one-sided."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Independent 2022 household outcome data are still thin, especially on whether transfers and pensions offset inflation.",
          "lenses": ["6B.2", "6B.8", "6B.10"],
          "best_source_or_query_direction": "Household microdata, nutrition/consumption surveys, MICS/DHS-style datasets, and program evaluations",
          "why_it_matters": "It distinguishes program reach from actual welfare change for ordinary households."
        }
      ],
      "reason": "The package fairly combines social-protection expansion with worsening inflation and poverty pressure, but much of the positive side remains programmatic rather than fully audited outcome evidence."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0025",
          "reason": "Country-level repression reporting is context for integrity, but it does not establish Sisi's personal truthfulness, self-dealing, or family benefit."
        },
        {
          "evidence_id": "E0059",
          "reason": "Structural military-economy analysis is useful baseline context, but it is not a forensic finding of ruler-specific enrichment or corruption."
        },
        {
          "evidence_id": "E0060",
          "reason": "Later retrospective investment-climate material is context only and should not be treated as direct evidence of personal integrity or dishonesty."
        },
        {
          "evidence_id": "E0082",
          "reason": "Press-freedom repression reporting shows tolerated abuse, but not a direct personal-nexus fact of Sisi's honesty or self-dealing."
        },
        {
          "evidence_id": "E0084",
          "reason": "The COP27 arrest campaign is strong repression evidence, but it does not itself prove personal enrichment, false statements, or private benefit."
        },
        {
          "evidence_id": "E0085",
          "reason": "The year-end repression synthesis is relevant context, but it should not be used as a substitute for direct ruler-specific integrity evidence."
        },
        {
          "evidence_id": "E0086",
          "reason": "The journalist arrest is a strong retaliation case, but it still does not show direct personal gain or a documented lie by Sisi himself."
        }
      ],
      "material_gaps": [
        {
          "gap": "There is no direct 2022 asset declaration, audit trail, procurement finding, or court judgment tying Sisi or close family to specific private gain from office.",
          "lenses": ["7B.3", "7B.4", "7B.6", "7B.7", "7B.9"],
          "best_source_or_query_direction": "Asset disclosures, procurement audits, court and inquiry records, parliamentary filings, and corroborated leaked documentation",
          "why_it_matters": "Without a personal-nexus record, the chapter risks collapsing authoritarian repression into personal dishonesty."
        },
        {
          "gap": "Direct truthfulness/correction evidence from Sisi's own statements is still thin.",
          "lenses": ["7B.1", "7B.2", "7B.8"],
          "best_source_or_query_direction": "Transcript-level speeches, official corrections/retractions, sworn testimony, and contemporaneous fact-checkable statements",
          "why_it_matters": "The chapter needs ruler-specific candor or deception evidence, not only institutional repression context."
        }
      ],
      "reason": "The dossier is strong on tolerated repression and selective clemency, but weak on the chapter's required personal-nexus evidence for honesty, self-dealing, or direct ruler-specific deception."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Direct evidence of Sisi's personal steering of tactical adjustments and durable outcome attribution remains limited.",
          "lenses": ["8B.4", "8B.8", "8B.10"],
          "best_source_or_query_direction": "Cabinet minutes, presidential directives, implementation audits, budget-execution data, and divestment records",
          "why_it_matters": "It separates formal program adoption from actual ruler-level execution and course correction."
        }
      ],
      "reason": "The follow-up materially clarified the 2022 program, implementation steps, and mixed outcomes, so the package can fairly present effectiveness even though the causal chain still leans heavily on official and multilateral framing."
    }
  ]
}
